window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[76]={"7600":{"example:7600:exzh":"She likes roses.","example:7600:exzh2":"Roses are beautiful flowers.","example:7600:exzh3":"I grow roses in the garden.","example:7600:exzh4":"The scent of roses is wonderful.","example:7600:exzh5":"I gave him a rose."},"7601":{"example:7601:exzh":"Oh my, what's wrong?","example:7601:exzh2":"Oh my, that's tough.","example:7601:exzh3":"Oh my, I'm late.","example:7601:exzh4":"Oh my, that surprised me.","example:7601:exzh5":"Oh my, that's not true at all."},"7603":{"example:7603:exzh":"That house has an old crest.","example:7603:exzh2":"A crest is a symbol of the family.","example:7603:exzh3":"He studied crest design.","example:7603:exzh4":"Crests have historical significance.","example:7603:exzh5":"There used to be craftsmen who made crests."},"7604":{"example:7604:exzh":"She likes to relax in the bathtub.","example:7604:exzh2":"I bought a new bathtub.","example:7604:exzh3":"I got in the bathtub and filled it with water.","example:7604:exzh4":"The bathtub is the center of the bathroom.","example:7604:exzh5":"I look forward to getting in the bathtub every night."},"7605":{"example:7605:exzh":"I'm learning dyeing techniques.","example:7605:exzh2":"This cloth has been given a special dye treatment.","example:7605:exzh3":"The dyeing class is a lot of fun.","example:7605:exzh4":"She is a dyeing artist.","example:7605:exzh5":"I use dyeing to create new designs."},"7606":{"example:7606:exzh":"This square is used to measure accurately.","example:7606:exzh2":"I used a square to draw the plans.","example:7606:exzh3":"The architect used a square to check the structure.","example:7606:exzh4":"I recorded the values measured with the square.","example:7606:exzh5":"A square is needed for accurate measurement."},"7607":{"example:7607:exzh":"This product is expensive, so please think it over carefully before buying.","example:7607:exzh2":"I'm worried about the high medical costs.","example:7607:exzh3":"High-income earners receive special tax benefits.","example:7607:exzh4":"This trip is expensive, but it's worth it.","example:7607:exzh5":"I signed a lease with very high rent."},"7609":{"example:7609:exzh":"Mountain climbing is one of my hobbies.","example:7609:exzh2":"I go mountain climbing with friends on weekends.","example:7609:exzh3":"I prepared the gear needed for mountain climbing.","example:7609:exzh4":"She goes mountain climbing every winter.","example:7609:exzh5":"Mountain climbing is a great way to enjoy nature."},"7610":{"example:7610:exzh":"This town has recently undergone a transformation.","example:7610:exzh2":"Through hard work, he was completely transformed.","example:7610:exzh3":"Environmental problems have driven the town's transformation.","example:7610:exzh4":"Technological progress has brought about a transformation of society.","example:7610:exzh5":"Companies need to transform to keep up with the times."},"7611":{"example:7611:exzh":"He was stripped of his rights.","example:7611:exzh2":"I'm thinking about the freedom that was taken away.","example:7611:exzh3":"Social deprivation is a serious problem.","example:7611:exzh4":"We need to analyze the causes of deprivation.","example:7611:exzh5":"This law aims to prevent deprivation."},"7612":{"example:7612:exzh":"He has a lump on his arm.","example:7612:exzh2":"This lump doesn't hurt.","example:7612:exzh3":"I asked the doctor why lumps form.","example:7612:exzh4":"If the lump gets bigger, let's go to the hospital.","example:7612:exzh5":"This kind of lump is usually not malignant."},"7613":{"example:7613:exzh":"He does writing work.","example:7613:exzh2":"It's important to concentrate when you write.","example:7613:exzh3":"Work on a new book has started.","example:7613:exzh4":"All the tools needed for writing are ready.","example:7613:exzh5":"She has a talent for writing."},"7614":{"example:7614:exzh":"There was an unexpected encounter.","example:7614:exzh2":"That event brought an unexpected result.","example:7614:exzh3":"I received unexpected news.","example:7614:exzh4":"He helped me out unexpectedly.","example:7614:exzh5":"This movie has an unexpected turn of events."},"7615":{"example:7615:exzh":"Geneva has beautiful lakes.","example:7615:exzh2":"He has been to Geneva.","example:7615:exzh3":"I'm very interested in the international organizations in Geneva.","example:7615:exzh4":"I visited the art museum in Geneva.","example:7615:exzh5":"An international conference will be held in Geneva."},"7617":{"example:7617:exzh":"He is complaining about the company.","example:7617:exzh2":"Let's think of a solution before complaining.","example:7617:exzh3":"She didn't voice any complaints.","example:7617:exzh4":"Complaints are sometimes necessary feedback.","example:7617:exzh5":"Everyone complained, so improvements were called for."},"7618":{"example:7618:exzh":"I like eating tacos.","example:7618:exzh2":"The tacos at this shop are really delicious.","example:7618:exzh3":"I made tacos with my friends.","example:7618:exzh4":"Tacos are Mexican food.","example:7618:exzh5":"Beer and tacos are the best combination."},"7619":{"example:7619:exzh":"Medicines need to be used properly.","example:7619:exzh2":"He works in the pharmaceutical field.","example:7619:exzh3":"Pharmaceutical research is very important.","example:7619:exzh4":"A new drug has been developed.","example:7619:exzh5":"It's dangerous without knowledge of medicines."},"7620":{"example:7620:exzh":"Lobster is a luxury dish.","example:7620:exzh2":"I ate lobster at a seafood restaurant.","example:7620:exzh3":"Lobster is a bit hard to eat.","example:7620:exzh4":"I love lobster dishes.","example:7620:exzh5":"I want to eat lobster on special days."},"7621":{"example:7621:exzh":"Let's meet again in the next life.","example:7621:exzh2":"He believes in the next life.","example:7621:exzh3":"I hope to live a good life in my next life.","example:7621:exzh4":"I'll do my best to be happy in my next life.","example:7621:exzh5":"I want to be reborn in my next life."},"7622":{"example:7622:exzh":"I bought a new tool.","example:7622:exzh2":"This tool is very handy.","example:7622:exzh3":"I got together the tools I need for work.","example:7622:exzh4":"I'll do the repairs together with my friend using tools.","example:7622:exzh5":"Where is the toolbox?"},"7623":{"example:7623:exzh":"I use a ladder to get to high places.","example:7623:exzh2":"The ladder is in the garage.","example:7623:exzh3":"This ladder is light and easy to carry.","example:7623:exzh4":"I used a ladder to repair the roof.","example:7623:exzh5":"Let's choose a ladder sturdier than an ordinary one."},"7624":{"example:7624:exzh":"What are we having for lunch today?","example:7624:exzh2":"I had sushi for lunch.","example:7624:exzh3":"Yesterday's lunch was a simple sandwich.","example:7624:exzh4":"Lunchtime is at 12.","example:7624:exzh5":"After work, I'm going to have lunch with a friend."},"7625":{"example:7625:exzh":"There's a lot of noise in this room.","example:7625:exzh2":"Let's close the window to reduce the noise.","example:7625:exzh3":"The noise from the music bothers me.","example:7625:exzh4":"The noise is too loud and I can't concentrate.","example:7625:exzh5":"This machine's selling point is that it makes little noise."},"7627":{"example:7627:exzh":"She bought a new bra.","example:7627:exzh2":"How a bra feels when you wear it is important.","example:7627:exzh3":"I wear a bra every day.","example:7627:exzh4":"It's necessary to measure your bra size.","example:7627:exzh5":"A bra is part of fashion."},"7628":{"example:7628:exzh":"I drank all the beer.","example:7628:exzh2":"I like drinking this juice all up.","example:7628:exzh3":"Please drink all the water in the glass.","example:7628:exzh4":"I finished all the drinks together with my friend.","example:7628:exzh5":"He always finishes his drink fast."},"7630":{"example:7630:exzh":"He saw through to her true feelings.","example:7630:exzh2":"It's not so easy to see through.","example:7630:exzh3":"Few people could see through this situation.","example:7630:exzh4":"She quickly saw through his lie.","example:7630:exzh5":"Develop your ability to see through things."},"7631":{"example:7631:exzh":"The script for this movie is really interesting.","example:7631:exzh2":"I read the script before performing.","example:7631:exzh3":"Please bring the script.","example:7631:exzh4":"He is writing a new script.","example:7631:exzh5":"Let's check the contents of the script."},"7632":{"example:7632:exzh":"That's a nonsense story.","example:7632:exzh2":"I think his opinion is nonsense.","example:7632:exzh3":"Don't use nonsense words.","example:7632:exzh4":"This question seems nonsensical.","example:7632:exzh5":"Her remarks are sometimes nonsense."},"7633":{"example:7633:exzh":"He is the spokesperson for that group.","example:7633:exzh2":"I can speak on your behalf.","example:7633:exzh3":"It's important to speak up for others.","example:7633:exzh4":"She spoke on behalf of a different opinion.","example:7633:exzh5":"Speaking on behalf of others can influence many people."},"7635":{"example:7635:exzh":"The meeting needs to be extended.","example:7635:exzh2":"The deadline can be extended.","example:7635:exzh3":"There's no point in dragging the conversation out.","example:7635:exzh4":"He is trying to extend the deadline.","example:7635:exzh5":"I decided to postpone the plan."},"7636":{"example:7636:exzh":"She is a lesbian.","example:7636:exzh2":"There are more and more lesbian couples.","example:7636:exzh3":"There needs to be understanding of lesbians.","example:7636:exzh4":"They don't hide that they are lesbians.","example:7636:exzh5":"Let's think about lesbian rights."},"7637":{"example:7637:exzh":"Knowledge about AIDS is needed.","example:7637:exzh2":"Getting tested for AIDS is important.","example:7637:exzh3":"Support for people with AIDS is needed.","example:7637:exzh4":"Preventing AIDS is important.","example:7637:exzh5":"I want to eliminate prejudice against AIDS."},"7639":{"example:7639:exzh":"He was able to recall the memory.","example:7639:exzh2":"That music brings back old memories for me.","example:7639:exzh3":"Her words rekindled hope.","example:7639:exzh4":"The movie evokes all kinds of emotions.","example:7639:exzh5":"The memories are brought back."},"7640":{"example:7640:exzh":"He's not the kind of person who backs down easily.","example:7640:exzh2":"Even when he's about to lose, he doesn't back down.","example:7640:exzh3":"I don't intend to back down.","example:7640:exzh4":"She fought to the end, but in the end she backed down.","example:7640:exzh5":"Backing down isn't an easy thing to do."},"7642":{"example:7642:exzh":"He became paralyzed on one side of his body.","example:7642:exzh2":"Half-body bathing is effective for relaxation.","example:7642:exzh3":"Half-body clothes are popular.","example:7642:exzh4":"I'm sitting with half of my body.","example:7642:exzh5":"I took a half-body photo."},"7643":{"example:7643:exzh":"Mom, what about dinner?","example:7643:exzh2":"Mom, let's go out and play!","example:7643:exzh3":"The sweets Mom makes are delicious.","example:7643:exzh4":"Mom goes to work every day.","example:7643:exzh5":"Mom, when is my birthday?","grammar:7643:ex:trans":"Mom, what're we doing about dinner?","grammar:7643:ex:structure":"かあ、晩ご飯は＋どうするの？ 「かあ」 = mom (a casual way of calling her); 「どうするの」 = what'll we do?","grammar:7643:ex:explain":"「かあ、晩ご飯はどうするの？」. 「かあ」 is a casual way of calling your mother, a more relaxed version of 「お母さん」 or 「母さん」. 「晩ご飯は」 raises dinner as the topic with 「は」. 「どうするの」 is a casual question: 「どうする」 means what will you do or how will you handle it, and the sentence-final 「の」 is a casual question particle that sounds warm and intimate. The line is a child asking their mother what's happening with dinner.","grammar:7643:ex:words:0:zh":"mom","grammar:7643:ex:words:0:note":"mom; a casual way of calling her","grammar:7643:ex:words:0:pos":"noun","grammar:7643:ex:words:1:zh":"dinner","grammar:7643:ex:words:1:note":"ばんごはん","grammar:7643:ex:words:1:pos":"noun","grammar:7643:ex:words:2:zh":"(topic marker)","grammar:7643:ex:words:2:pos":"particle","grammar:7643:ex:words:3:zh":"what to do","grammar:7643:ex:words:3:note":"casual question","grammar:7643:ex:words:3:pos":"Expression","grammar:7643:ex:points:0":"かあ: mom (when calling her; = お母さん / 母さん)","grammar:7643:ex:points:1":"どうするの: what'll we do? (casual)","grammar:7643:ex2:trans":"Mom, let's go out and have fun!","grammar:7643:ex2:structure":"かあ、〔遊びに〕＋行こう！ 「行こう」 is the volitional form: let's go.","grammar:7643:ex2:words:0:zh":"mom","grammar:7643:ex2:words:0:note":"mom","grammar:7643:ex2:words:0:pos":"noun","grammar:7643:ex2:words:1:zh":"to play (go to…)","grammar:7643:ex2:words:1:note":"masu-stem + に","grammar:7643:ex2:words:1:pos":"verb","grammar:7643:ex2:words:2:zh":"(purpose)","grammar:7643:ex2:words:2:pos":"particle","grammar:7643:ex2:words:3:zh":"let's go","grammar:7643:ex2:words:3:note":"volitional form","grammar:7643:ex2:words:3:pos":"verb","grammar:7643:ex2:points:0":"volitional form: 行く→行こう (let's go)","grammar:7643:ex2:points:1":"遊びに行く: to go out and have fun","grammar:7643:ex3:trans":"The sweets Mom makes are delicious.","grammar:7643:ex3:structure":"〔かあが作った〕＋お菓子＋は＋美味しい. 「かあが作った」 modifies 「お菓子」.","grammar:7643:ex3:words:0:zh":"mom","grammar:7643:ex3:words:0:note":"mom","grammar:7643:ex3:words:0:pos":"noun","grammar:7643:ex3:words:1:zh":"(nominative)","grammar:7643:ex3:words:1:note":"clause","grammar:7643:ex3:words:1:pos":"particle","grammar:7643:ex3:words:2:zh":"made","grammar:7643:ex3:words:2:note":"ta-form modification","grammar:7643:ex3:words:2:pos":"verb","grammar:7643:ex3:words:3:zh":"sweets","grammar:7643:ex3:words:3:note":"おかし","grammar:7643:ex3:words:3:pos":"noun","grammar:7643:ex3:words:4:zh":"(topic marker)","grammar:7643:ex3:words:4:pos":"particle","grammar:7643:ex3:words:5:zh":"tasty","grammar:7643:ex3:words:5:note":"おいしい","grammar:7643:ex3:words:5:pos":"adjective","grammar:7643:ex3:points:0":"ta-form of a verb modifying a noun: 作ったお菓子 (sweets that were made)","grammar:7643:ex3:points:1":"〜が作った: made by …","grammar:7643:ex4:trans":"Mom goes to work every day.","grammar:7643:ex4:structure":"かあは、毎日＋仕事に＋行きます. 「仕事に行く」 = to go to work.","grammar:7643:ex4:words:0:zh":"mom","grammar:7643:ex4:words:0:note":"mom","grammar:7643:ex4:words:0:pos":"noun","grammar:7643:ex4:words:1:zh":"(topic marker)","grammar:7643:ex4:words:1:pos":"particle","grammar:7643:ex4:words:2:zh":"every day","grammar:7643:ex4:words:2:note":"まいにち","grammar:7643:ex4:words:2:pos":"noun","grammar:7643:ex4:words:3:zh":"work","grammar:7643:ex4:words:3:note":"しごと","grammar:7643:ex4:words:3:pos":"noun","grammar:7643:ex4:words:4:zh":"(purpose)","grammar:7643:ex4:words:4:pos":"particle","grammar:7643:ex4:words:5:zh":"go","grammar:7643:ex4:words:5:note":"いきます","grammar:7643:ex4:words:5:pos":"verb","grammar:7643:ex4:points:0":"仕事に行く: to go to work","grammar:7643:ex4:points:1":"毎日: every day","grammar:7643:ex5:trans":"Mom, when's my birthday?","grammar:7643:ex5:structure":"かあ、〔私の誕生日〕＋は＋いつ？ 「いつ」 = when.","grammar:7643:ex5:words:0:zh":"mom","grammar:7643:ex5:words:0:note":"mom","grammar:7643:ex5:words:0:pos":"noun","grammar:7643:ex5:words:1:zh":"I","grammar:7643:ex5:words:1:note":"わたし","grammar:7643:ex5:words:1:pos":"pronoun","grammar:7643:ex5:words:2:zh":"'s","grammar:7643:ex5:words:2:pos":"particle","grammar:7643:ex5:words:3:zh":"birthday","grammar:7643:ex5:words:3:note":"たんじょうび","grammar:7643:ex5:words:3:pos":"noun","grammar:7643:ex5:words:4:zh":"(topic marker)","grammar:7643:ex5:words:4:pos":"particle","grammar:7643:ex5:words:5:zh":"when","grammar:7643:ex5:words:5:pos":"question word","grammar:7643:ex5:points:0":"いつ：when","grammar:7643:ex5:points:1":"私の誕生日: my birthday"},"7644":{"example:7644:exzh":"I like driving a car.","example:7644:exzh2":"I bought a new car.","example:7644:exzh3":"There's a lot of car traffic.","example:7644:exzh4":"Please watch out for car accidents.","example:7644:exzh5":"Cars are convenient.","grammar:7644:ex:trans":"I like driving a car.","grammar:7644:ex:structure":"〜のが好きです","grammar:7644:ex:explain":"「自動車を運転するのが好きです」. 「自動車」 is read 「じどうしゃ」 and is the formal word for car; casual speech mostly uses 「車（くるま）」. The pattern is 「〔verb phrase〕のが好き」: 「自動車を運転する」 is nominalized with 「の」, then 「が」 marks the object of 「好き」. Note that the object of liking takes 「が」, not 「を」. The whole sentence means I like driving a car.","grammar:7644:ex:words:0:zh":"car","grammar:7644:ex:words:0:note":"じどうしゃ","grammar:7644:ex:words:0:pos":"noun","grammar:7644:ex:words:1:zh":"(object marker)","grammar:7644:ex:words:1:pos":"particle","grammar:7644:ex:words:2:zh":"driving","grammar:7644:ex:words:2:note":"うんてんする","grammar:7644:ex:words:2:pos":"verb","grammar:7644:ex:words:3:zh":"(nominalizer)","grammar:7644:ex:words:3:pos":"particle","grammar:7644:ex:words:4:zh":"(object)","grammar:7644:ex:words:4:pos":"particle","grammar:7644:ex:words:5:zh":"to like","grammar:7644:ex:words:5:note":"すき","grammar:7644:ex:words:5:pos":"na-adjective","grammar:7644:ex:words:6:zh":"(polite form)","grammar:7644:ex:words:6:pos":"copula","grammar:7644:ex:points:0":"❗自動車（じどうしゃ）: car (formal; casual 車 くるま).","grammar:7644:ex:points:1":"運転する: drive.","grammar:7644:ex2:trans":"I bought a new car.","grammar:7644:ex2:structure":"〜を買いました","grammar:7644:ex2:words:0:zh":"new","grammar:7644:ex2:words:0:note":"あたらしい","grammar:7644:ex2:words:0:pos":"adjective","grammar:7644:ex2:words:1:zh":"car","grammar:7644:ex2:words:1:note":"じどうしゃ","grammar:7644:ex2:words:1:pos":"noun","grammar:7644:ex2:words:2:zh":"(object marker)","grammar:7644:ex2:words:2:pos":"particle","grammar:7644:ex2:words:3:zh":"bought","grammar:7644:ex2:words:3:note":"かいました","grammar:7644:ex2:words:3:pos":"verb","grammar:7644:ex2:points:0":"新しい自動車: a new car.","grammar:7644:ex2:points:1":"買う→買いました。","grammar:7644:ex3:trans":"There's a lot of car traffic.","grammar:7644:ex3:structure":"〜が多いです","grammar:7644:ex3:words:0:zh":"car","grammar:7644:ex3:words:0:note":"じどうしゃ","grammar:7644:ex3:words:0:pos":"noun","grammar:7644:ex3:words:1:zh":"'s","grammar:7644:ex3:words:1:pos":"particle","grammar:7644:ex3:words:2:zh":"transportation","grammar:7644:ex3:words:2:note":"こうつう","grammar:7644:ex3:words:2:pos":"noun","grammar:7644:ex3:words:3:zh":"(nominative)","grammar:7644:ex3:words:3:pos":"particle","grammar:7644:ex3:words:4:zh":"many","grammar:7644:ex3:words:4:note":"おおい","grammar:7644:ex3:words:4:pos":"adjective","grammar:7644:ex3:words:5:zh":"(polite form)","grammar:7644:ex3:words:5:pos":"copula","grammar:7644:ex3:points:0":"交通が多い: heavy traffic.","grammar:7644:ex3:points:1":"自動車の交通: car traffic.","grammar:7644:ex4:trans":"Please watch out for car accidents.","grammar:7644:ex4:structure":"〜に注意してください","grammar:7644:ex4:words:0:zh":"car accident","grammar:7644:ex4:words:0:note":"じどうしゃじこ","grammar:7644:ex4:words:0:pos":"noun","grammar:7644:ex4:words:1:zh":"(object)","grammar:7644:ex4:words:1:pos":"particle","grammar:7644:ex4:words:2:zh":"be careful","grammar:7644:ex4:words:2:note":"ちゅういして","grammar:7644:ex4:words:2:pos":"verb","grammar:7644:ex4:words:3:zh":"please","grammar:7644:ex4:words:3:pos":"auxiliary verb","grammar:7644:ex4:points:0":"❗自動車事故: car accident.","grammar:7644:ex4:points:1":"〜に注意する: pay attention to …","grammar:7644:ex5:trans":"Cars are convenient.","grammar:7644:ex5:structure":"〜は便利です","grammar:7644:ex5:words:0:zh":"car","grammar:7644:ex5:words:0:note":"じどうしゃ","grammar:7644:ex5:words:0:pos":"noun","grammar:7644:ex5:words:1:zh":"(topic)","grammar:7644:ex5:words:1:pos":"particle","grammar:7644:ex5:words:2:zh":"convenient","grammar:7644:ex5:words:2:note":"べんり","grammar:7644:ex5:words:2:pos":"na-adjective","grammar:7644:ex5:words:3:zh":"(polite form)","grammar:7644:ex5:words:3:pos":"copula","grammar:7644:ex5:points:0":"便利: convenient.","grammar:7644:ex5:points:1":"自動車は: cars (topic)."},"7645":{"example:7645:exzh":"Her dress is bright red.","example:7645:exzh2":"I like bright red apples.","example:7645:exzh3":"The sky turned bright red.","example:7645:exzh4":"Bright red flowers are blooming.","example:7645:exzh5":"He turned bright red with embarrassment.","grammar:7645:ex:trans":"Her dress is bright red.","grammar:7645:ex:structure":"ドレスは＋真っ赤です","grammar:7645:ex:explain":"「彼女のドレスは真っ赤です」. The key point is the prefix 「真っ」, attached to colors and states to emphasize the degree; 「真っ」 plus 「赤」 makes 「真っ赤」, meaning 「bright red, vivid red」, stronger than plain 「赤い」. Similar forms include 「真っ白、真っ黒、真っ青」. 「真っ赤」 is a na-adjective, and 「です」 makes it a polite statement. The whole sentence is 「Her dress is bright red」.","grammar:7645:ex:words:0:zh":"she","grammar:7645:ex:words:0:note":"かのじょ","grammar:7645:ex:words:0:pos":"pronoun","grammar:7645:ex:words:1:zh":"'s","grammar:7645:ex:words:1:pos":"particle","grammar:7645:ex:words:2:zh":"dress","grammar:7645:ex:words:2:pos":"noun","grammar:7645:ex:words:3:zh":"(topic)","grammar:7645:ex:words:3:pos":"particle","grammar:7645:ex:words:4:zh":"bright red","grammar:7645:ex:words:4:note":"まっか","grammar:7645:ex:words:4:pos":"na-adjective","grammar:7645:ex:words:5:zh":"(assertion · polite)","grammar:7645:ex:words:5:pos":"auxiliary verb","grammar:7645:ex:points:0":"prefix 「真っ」＋赤 ＝ 真っ赤 (bright red, intensifying the degree)","grammar:7645:ex:points:1":"na-adjective polite copula: 真っ赤です","grammar:7645:ex2:trans":"I like bright red apples.","grammar:7645:ex2:structure":"真っ赤なリンゴ＋が好きです","grammar:7645:ex2:words:0:zh":"bright red","grammar:7645:ex2:words:0:note":"まっか","grammar:7645:ex2:words:0:pos":"na-adjective","grammar:7645:ex2:words:1:zh":"(attributive form)","grammar:7645:ex2:words:1:pos":"auxiliary verb","grammar:7645:ex2:words:2:zh":"apple","grammar:7645:ex2:words:2:pos":"noun","grammar:7645:ex2:words:3:zh":"(object)","grammar:7645:ex2:words:3:pos":"particle","grammar:7645:ex2:words:4:zh":"to like","grammar:7645:ex2:words:4:note":"すき","grammar:7645:ex2:words:4:pos":"na-adjective","grammar:7645:ex2:words:5:zh":"(assertion · polite)","grammar:7645:ex2:words:5:pos":"auxiliary verb","grammar:7645:ex2:points:0":"na-adjective pre-nominal form: 真っ赤な＋リンゴ (bright red apples)","grammar:7645:ex2:points:1":"〜が好きだ: like 〜","grammar:7645:ex3:trans":"The sky was dyed bright red.","grammar:7645:ex3:structure":"空が真っ赤に＋染まった","grammar:7645:ex3:words:0:zh":"sky","grammar:7645:ex3:words:0:note":"そら","grammar:7645:ex3:words:0:pos":"noun","grammar:7645:ex3:words:1:zh":"(nominative)","grammar:7645:ex3:words:1:pos":"particle","grammar:7645:ex3:words:2:zh":"bright red","grammar:7645:ex3:words:2:note":"まっか","grammar:7645:ex3:words:2:pos":"na-adjective","grammar:7645:ex3:words:3:zh":"(resulting state)","grammar:7645:ex3:words:3:pos":"particle","grammar:7645:ex3:words:4:zh":"get dyed","grammar:7645:ex3:words:4:note":"そまった","grammar:7645:ex3:words:4:pos":"verb","grammar:7645:ex3:points:0":"na-adjective ＋に＋染まる: to be dyed 〜 (真っ赤に染まる ＝ to be dyed bright red)","grammar:7645:ex3:points:1":"「染まる」 godan intransitive verb (to be dyed, to take on a color)","grammar:7645:ex4:trans":"Bright red flowers are blooming.","grammar:7645:ex4:structure":"真っ赤な花が＋咲いている","grammar:7645:ex4:words:0:zh":"bright red","grammar:7645:ex4:words:0:note":"まっか","grammar:7645:ex4:words:0:pos":"na-adjective","grammar:7645:ex4:words:1:zh":"(attributive form)","grammar:7645:ex4:words:1:pos":"auxiliary verb","grammar:7645:ex4:words:2:zh":"flowers","grammar:7645:ex4:words:2:note":"はな","grammar:7645:ex4:words:2:pos":"noun","grammar:7645:ex4:words:3:zh":"(nominative)","grammar:7645:ex4:words:3:pos":"particle","grammar:7645:ex4:words:4:zh":"to bloom","grammar:7645:ex4:words:4:note":"さいて (te-form)","grammar:7645:ex4:words:4:pos":"verb","grammar:7645:ex4:words:5:zh":"(ongoing state)","grammar:7645:ex4:words:5:pos":"auxiliary verb","grammar:7645:ex4:points:0":"na-adjective pre-nominal form: 真っ赤な＋花 (bright red flowers)","grammar:7645:ex4:points:1":"〜ている: here it expresses an ongoing state (are in bloom)","grammar:7645:ex5:trans":"He turned bright red with embarrassment.","grammar:7645:ex5:structure":"真っ赤になって＋恥ずかしい","grammar:7645:ex5:words:0:zh":"he","grammar:7645:ex5:words:0:note":"かれ","grammar:7645:ex5:words:0:pos":"pronoun","grammar:7645:ex5:words:1:zh":"(topic)","grammar:7645:ex5:words:1:pos":"particle","grammar:7645:ex5:words:2:zh":"bright red","grammar:7645:ex5:words:2:note":"まっか","grammar:7645:ex5:words:2:pos":"na-adjective","grammar:7645:ex5:words:3:zh":"(resulting state)","grammar:7645:ex5:words:3:pos":"particle","grammar:7645:ex5:words:4:zh":"become","grammar:7645:ex5:words:4:note":"なって (te-form)","grammar:7645:ex5:words:4:pos":"verb","grammar:7645:ex5:words:5:zh":"embarrassed; shy","grammar:7645:ex5:words:5:note":"はずかしい","grammar:7645:ex5:words:5:pos":"adjective","grammar:7645:ex5:points:0":"na-adjective ＋に＋なる: 真っ赤になる (to turn bright red)","grammar:7645:ex5:points:1":"te-form link: 真っ赤になって (turning red, and…)"},"7646":{"example:7646:exzh":"A stain got on the clothes.","example:7646:exzh2":"Please be careful not to get spots.","example:7646:exzh3":"That stain wouldn't come out.","example:7646:exzh4":"I'll use a spot-removal cream.","example:7646:exzh5":"I get embarrassed when I have spots."},"7647":{"example:7647:exzh":"The two companies formed a partnership.","example:7647:exzh2":"There are lots of benefits to a partnership.","example:7647:exzh3":"They are building a partnership.","example:7647:exzh4":"The partnership produced a new product.","example:7647:exzh5":"We'll hold a meeting with our partner company."},"7648":{"example:7648:exzh":"He transcended his own limits.","example:7648:exzh2":"This work transcends time.","example:7648:exzh3":"We must transcend hardship.","example:7648:exzh4":"His talent goes beyond common sense.","example:7648:exzh5":"I'll do my best with a spirit of transcendence."},"7650":{"example:7650:exzh":"These clothes are too big for me.","example:7650:exzh2":"Excessive expectations can lead to disappointment.","example:7650:exzh3":"That plan sets overly ambitious goals.","example:7650:exzh4":"This size is too big, so please try another size.","example:7650:exzh5":"You should avoid taking excessive risks."},"7651":{"example:7651:exzh":"Iron Man is a popular movie.","example:7651:exzh2":"The kids like the Iron Man character.","example:7651:exzh3":"Iron Man's costume is really cool.","example:7651:exzh4":"I want an Iron Man figure.","example:7651:exzh5":"The Iron Man story is interesting."},"7652":{"example:7652:exzh":"I hurt my right leg.","example:7652:exzh2":"Please jump using your right leg.","example:7652:exzh3":"He is holding down something heavy with his right leg.","example:7652:exzh4":"It's comfortable to sit with my right leg crossed.","example:7652:exzh5":"My right leg hurts, so I'll rest.","grammar:7652:ex:trans":"I injured my right leg.","grammar:7652:ex:structure":"〜は＋noun＋を＋怪我しました. 「〜を怪我する」 = to injure (a body part); 「右足」 = the right leg.","grammar:7652:ex:explain":"「私は右足を怪我しました」. The core is 「〜を怪我する」, meaning to injure (some part of the body), with the injured part marked by 「を」. It might seem natural to make the leg the subject, but Japanese prefers the transitive 「（body part）を怪我する」 with the person, 「私」, as the subject. 「怪我しました」 is the polite past form. 「右足」 is read みぎあし and means the right leg.","grammar:7652:ex:words:0:zh":"I","grammar:7652:ex:words:0:note":"わたし","grammar:7652:ex:words:0:pos":"pronoun","grammar:7652:ex:words:1:zh":"(topic marker)","grammar:7652:ex:words:1:pos":"particle","grammar:7652:ex:words:2:zh":"right leg","grammar:7652:ex:words:2:note":"みぎあし","grammar:7652:ex:words:2:pos":"noun","grammar:7652:ex:words:3:zh":"(object marker)","grammar:7652:ex:words:3:pos":"particle","grammar:7652:ex:words:4:zh":"got injured","grammar:7652:ex:words:4:note":"けがしました","grammar:7652:ex:words:4:pos":"verb","grammar:7652:ex:points:0":"右足 (みぎあし): the right leg","grammar:7652:ex:points:1":"〜を怪我する: to injure (a body part)","grammar:7652:ex2:trans":"Please jump with your right leg.","grammar:7652:ex2:structure":"右足を＋〔使って〕、ジャンプしてください. 「〜を使って」 = using … (means).","grammar:7652:ex2:words:0:zh":"right leg","grammar:7652:ex2:words:0:note":"みぎあし","grammar:7652:ex2:words:0:pos":"noun","grammar:7652:ex2:words:1:zh":"(object marker)","grammar:7652:ex2:words:1:pos":"particle","grammar:7652:ex2:words:2:zh":"using (and then)","grammar:7652:ex2:words:2:note":"te-form expressing means","grammar:7652:ex2:words:2:pos":"verb","grammar:7652:ex2:words:3:zh":"jump","grammar:7652:ex2:words:3:note":"te-form","grammar:7652:ex2:words:3:pos":"verb","grammar:7652:ex2:words:4:zh":"please","grammar:7652:ex2:words:4:note":"〜てください","grammar:7652:ex2:words:4:pos":"verb","grammar:7652:ex2:points:0":"〜を使って: using … (means)","grammar:7652:ex2:points:1":"ジャンプする: to jump","grammar:7652:ex3:trans":"He is holding down something heavy with his right leg.","grammar:7652:ex3:structure":"body part＋で＋〜を押さえています","grammar:7652:ex3:explain":"「右足で」 tells us which body part he is using to hold the thing down. 「重い」 modifies 「もの」 directly, and 「を」 marks what is being held down. 「押さえる」 emphasizes pressing and keeping something fixed in place, and here 「〜ています」 shows that he is keeping that action going right now.","grammar:7652:ex3:words:0:zh":"he","grammar:7652:ex3:words:0:note":"かれ","grammar:7652:ex3:words:0:pos":"pronoun","grammar:7652:ex3:words:1:zh":"(introduces the topic)","grammar:7652:ex3:words:1:pos":"particle","grammar:7652:ex3:words:2:zh":"right leg","grammar:7652:ex3:words:2:note":"みぎあし","grammar:7652:ex3:words:2:pos":"noun","grammar:7652:ex3:words:3:zh":"(tool, means)","grammar:7652:ex3:words:3:pos":"particle","grammar:7652:ex3:words:4:zh":"heavy","grammar:7652:ex3:words:4:note":"おもい","grammar:7652:ex3:words:4:pos":"i-adjective","grammar:7652:ex3:words:5:zh":"things","grammar:7652:ex3:words:5:pos":"noun","grammar:7652:ex3:words:6:zh":"(object)","grammar:7652:ex3:words:6:pos":"particle","grammar:7652:ex3:words:7:zh":"to hold down, to press down","grammar:7652:ex3:words:7:note":"おさえ","grammar:7652:ex3:words:7:pos":"verb","grammar:7652:ex3:words:8:zh":"(links to an ongoing action)","grammar:7652:ex3:words:8:pos":"particle","grammar:7652:ex3:words:9:zh":"(the action is ongoing)","grammar:7652:ex3:words:9:pos":"verb","grammar:7652:ex3:words:10:zh":"(polite ending)","grammar:7652:ex3:words:10:pos":"auxiliary verb","grammar:7652:ex3:points:0":"The 「で」 in 「右足で」 marks the means being used, and it can also mark a body part.","grammar:7652:ex3:points:1":"「押さえています」 means holding something down continuously so that it doesn't move.","grammar:7652:ex4:trans":"Sitting with the right leg crossed over is comfortable.","grammar:7652:ex4:structure":"〔右足を組んで座る＋の〕＋は＋楽です. 「足を組む」 = to cross one's legs; 「組んで」 is the te-form linking the verbs.","grammar:7652:ex4:words:0:zh":"right leg","grammar:7652:ex4:words:0:note":"みぎあし","grammar:7652:ex4:words:0:pos":"noun","grammar:7652:ex4:words:1:zh":"(object marker)","grammar:7652:ex4:words:1:pos":"particle","grammar:7652:ex4:words:2:zh":"cross (and)","grammar:7652:ex4:words:2:note":"くんで；te-form","grammar:7652:ex4:words:2:pos":"verb","grammar:7652:ex4:words:3:zh":"sit","grammar:7652:ex4:words:3:note":"すわる; dictionary form","grammar:7652:ex4:words:3:pos":"verb","grammar:7652:ex4:words:4:zh":"(nominalizer)","grammar:7652:ex4:words:4:pos":"particle","grammar:7652:ex4:words:5:zh":"(topic marker)","grammar:7652:ex4:words:5:pos":"particle","grammar:7652:ex4:words:6:zh":"comfortable","grammar:7652:ex4:words:6:note":"らく","grammar:7652:ex4:words:6:pos":"na-adjective","grammar:7652:ex4:words:7:zh":"(polite form)","grammar:7652:ex4:words:7:pos":"copula","grammar:7652:ex4:points:0":"足を組む: to cross one's legs, to sit cross-legged","grammar:7652:ex4:points:1":"verb＋の＋は楽: it is comfortable to …","grammar:7652:ex5:trans":"My right leg hurts, so I'll take a rest.","grammar:7652:ex5:structure":"〔右足が痛い＋ので〕、休みます. 「〜ので」 gives the reason.","grammar:7652:ex5:words:0:zh":"right leg","grammar:7652:ex5:words:0:note":"みぎあし","grammar:7652:ex5:words:0:pos":"noun","grammar:7652:ex5:words:1:zh":"(nominative)","grammar:7652:ex5:words:1:pos":"particle","grammar:7652:ex5:words:2:zh":"painful","grammar:7652:ex5:words:2:note":"いたい","grammar:7652:ex5:words:2:pos":"adjective","grammar:7652:ex5:words:3:zh":"because","grammar:7652:ex5:words:3:note":"cause / reason","grammar:7652:ex5:words:3:pos":"particle","grammar:7652:ex5:words:4:zh":"rest","grammar:7652:ex5:words:4:note":"やすみます","grammar:7652:ex5:words:4:pos":"verb","grammar:7652:ex5:points:0":"〜ので: because … (reason)","grammar:7652:ex5:points:1":"右足が痛い: the right leg hurts"},"7653":{"example:7653:exzh":"Singapore is a beautiful country.","example:7653:exzh2":"Singapore has lots of delicious food.","example:7653:exzh3":"I've been to Singapore.","example:7653:exzh4":"Singapore is a multicultural country.","example:7653:exzh5":"Singapore's night view is wonderful."},"7654":{"example:7654:exzh":"He is called Hirose.","example:7654:exzh2":"Hirose's family is very kind.","example:7654:exzh3":"She lives with Hirose.","example:7654:exzh4":"Hirose's friend is coming.","example:7654:exzh5":"Hirose is my classmate at school."},"7655":{"example:7655:exzh":"The new employee is undergoing training.","example:7655:exzh2":"A welcome party for new students will be held.","example:7655:exzh3":"The new person in charge has been decided.","example:7655:exzh4":"A new member has joined the team.","example:7655:exzh5":"New employees have a special orientation."},"7656":{"example:7656:exzh":"I'll make an omelet for breakfast.","example:7656:exzh2":"You can put vegetables in an omelet.","example:7656:exzh3":"I love omelets.","example:7656:exzh4":"Omelets are a breakfast staple.","example:7656:exzh5":"You can use whatever ingredients you like in an omelet."},"7657":{"example:7657:exzh":"The samurai fought wearing a helmet.","example:7657:exzh2":"This helmet has historical value.","example:7657:exzh3":"I saw someone wearing a helmet.","example:7657:exzh4":"The helmet is traditional Japanese armor.","example:7657:exzh5":"At the campsite, I used a helmet to start a fire."},"7658":{"example:7658:exzh":"This chair is sturdy.","example:7658:exzh2":"I want to build a strong body.","example:7658:exzh3":"It's made of durable materials.","example:7658:exzh4":"He's healthy, so he rarely catches colds.","example:7658:exzh5":"This bag is sturdy and long-lasting.","grammar:7658:ex:trans":"This chair is sturdy.","grammar:7658:ex:structure":"この＋noun＋は＋na-adjective＋です。 「丈夫」 means sturdy, solid.","grammar:7658:ex:explain":"「この椅子は丈夫です」。 The core is the na-adjective 「丈夫」, meaning sturdy or solid; here it describes a chair as well built. 「丈夫」 can also describe a person as healthy, so context decides. The pattern is AはBです, with the na-adjective as the predicate plus 「です」 for polite assertion. 「この椅子」 is modified by the pre-noun adjectival 「この」. The whole sentence means this chair is sturdy.","grammar:7658:ex:words:0:zh":"this","grammar:7658:ex:words:0:pos":"pre-noun adjectival","grammar:7658:ex:words:1:zh":"chair","grammar:7658:ex:words:1:note":"いす","grammar:7658:ex:words:1:pos":"noun","grammar:7658:ex:words:2:zh":"(topic marker)","grammar:7658:ex:words:2:pos":"particle","grammar:7658:ex:words:3:zh":"sturdy","grammar:7658:ex:words:3:note":"じょうぶ","grammar:7658:ex:words:3:pos":"na-adjective","grammar:7658:ex:words:4:zh":"(polite form)","grammar:7658:ex:words:4:pos":"copula","grammar:7658:ex:points:0":"丈夫: sturdy, solid (for objects); can also mean healthy","grammar:7658:ex:points:1":"この椅子: this chair","grammar:7658:ex2:trans":"I want to build a healthy body.","grammar:7658:ex2:structure":"〔a healthy body〕＋を＋作りたいです。 「丈夫な」 takes な to modify a noun. Here it means good health.","grammar:7658:ex2:words:0:zh":"healthy","grammar:7658:ex2:words:0:note":"じょうぶ","grammar:7658:ex2:words:0:pos":"na-adjective","grammar:7658:ex2:words:1:zh":"body","grammar:7658:ex2:words:1:note":"からだ","grammar:7658:ex2:words:1:pos":"noun","grammar:7658:ex2:words:2:zh":"(object marker)","grammar:7658:ex2:words:2:pos":"particle","grammar:7658:ex2:words:3:zh":"to want to build","grammar:7658:ex2:words:3:note":"〜たい expresses desire","grammar:7658:ex2:words:3:pos":"verb","grammar:7658:ex2:words:4:zh":"(polite form)","grammar:7658:ex2:words:4:pos":"copula","grammar:7658:ex2:points:0":"丈夫な体: a healthy, strong body","grammar:7658:ex2:points:1":"〜たい: want to …","grammar:7658:ex3:trans":"It's made from sturdy materials.","grammar:7658:ex3:structure":"〔sturdy materials〕＋で＋作られています。 「で」 marks material, and 「作られている」 means is made (passive form).","grammar:7658:ex3:words:0:zh":"strong","grammar:7658:ex3:words:0:note":"じょうぶ","grammar:7658:ex3:words:0:pos":"na-adjective","grammar:7658:ex3:words:1:zh":"ingredient","grammar:7658:ex3:words:1:note":"ざいりょう","grammar:7658:ex3:words:1:pos":"noun","grammar:7658:ex3:words:2:zh":"use","grammar:7658:ex3:words:2:note":"material","grammar:7658:ex3:words:2:pos":"particle","grammar:7658:ex3:words:3:zh":"was made","grammar:7658:ex3:words:3:note":"passive＋ている","grammar:7658:ex3:words:3:pos":"verb","grammar:7658:ex3:points:0":"で: with, from … (material; 丈夫な材料で = from sturdy materials)","grammar:7658:ex3:points:1":"作られている: is made (passive form＋ている)","grammar:7658:ex4:trans":"He's healthy, so he doesn't catch colds easily.","grammar:7658:ex4:structure":"〜は＋〔丈夫なので〕、風邪を＋ひきにくいです。 「na-adjective＋なので」 marks a cause, and 「〜にくい」 means hard to ….","grammar:7658:ex4:words:0:zh":"he","grammar:7658:ex4:words:0:note":"かれ","grammar:7658:ex4:words:0:pos":"pronoun","grammar:7658:ex4:words:1:zh":"(topic marker)","grammar:7658:ex4:words:1:pos":"particle","grammar:7658:ex4:words:2:zh":"health","grammar:7658:ex4:words:2:note":"じょうぶ","grammar:7658:ex4:words:2:pos":"na-adjective","grammar:7658:ex4:words:3:zh":"(na-adjective connection)","grammar:7658:ex4:words:3:note":"丈夫なので","grammar:7658:ex4:words:3:pos":"copula","grammar:7658:ex4:words:4:zh":"because","grammar:7658:ex4:words:4:note":"cause / reason","grammar:7658:ex4:words:4:pos":"particle","grammar:7658:ex4:words:5:zh":"a cold","grammar:7658:ex4:words:5:note":"かぜ","grammar:7658:ex4:words:5:pos":"noun","grammar:7658:ex4:words:6:zh":"(object marker)","grammar:7658:ex4:words:6:pos":"particle","grammar:7658:ex4:words:7:zh":"hard to catch","grammar:7658:ex4:words:7:note":"〜にくい","grammar:7658:ex4:words:7:pos":"adjective","grammar:7658:ex4:words:8:zh":"(polite form)","grammar:7658:ex4:words:8:pos":"copula","grammar:7658:ex4:points:0":"na-adjective＋なので: because … (丈夫なので = because he's healthy)","grammar:7658:ex4:points:1":"verb masu-stem＋にくい: hard to … (ひきにくい = hard to catch a cold)","grammar:7658:ex5:trans":"This bag is sturdy and long-lasting.","grammar:7658:ex5:structure":"この＋noun＋は＋〔丈夫で〕、長持ちします。 「丈夫で」 means sturdy and (the te-form of a na-adjective), and 「長持ちする」 means to last a long time.","grammar:7658:ex5:words:0:zh":"this","grammar:7658:ex5:words:0:pos":"pre-noun adjectival","grammar:7658:ex5:words:1:zh":"bag","grammar:7658:ex5:words:1:note":"loanword","grammar:7658:ex5:words:1:pos":"noun","grammar:7658:ex5:words:2:zh":"(topic marker)","grammar:7658:ex5:words:2:pos":"particle","grammar:7658:ex5:words:3:zh":"sturdy","grammar:7658:ex5:words:3:note":"じょうぶ","grammar:7658:ex5:words:3:pos":"na-adjective","grammar:7658:ex5:words:4:zh":"(te-form)","grammar:7658:ex5:words:4:note":"だ→で","grammar:7658:ex5:words:4:pos":"copula","grammar:7658:ex5:words:5:zh":"durable","grammar:7658:ex5:words:5:note":"ながもちします","grammar:7658:ex5:words:5:pos":"verb","grammar:7658:ex5:points:0":"na-adjective te-form: 丈夫 → 丈夫で (sturdy, and …)","grammar:7658:ex5:points:1":"長持ちする: to last long, to be durable"},"7659":{"example:7659:exzh":"I'm sorry for causing you trouble.","example:7659:exzh2":"I'm sorry to impose, but let me help you.","example:7659:exzh3":"I'm sorry, but could you explain it once more?","example:7659:exzh4":"I feel rather overwhelmed by this gift.","example:7659:exzh5":"I'm sorry, but could you give up your seat?"},"7660":{"example:7660:exzh":"This fabric is soft and flexible.","example:7660:exzh2":"I'm doing flexibility exercises.","example:7660:exzh3":"I need a flexible material.","example:7660:exzh4":"Flexible thinking is important.","example:7660:exzh5":"She's good at stretching exercises."},"7661":{"example:7661:exzh":"This place is noisy.","example:7661:exzh2":"I can hear a noisy sound.","example:7661:exzh3":"The kids are playing noisily.","example:7661:exzh4":"I like noisy streets.","example:7661:exzh5":"That party was very noisy."},"7662":{"example:7662:exzh":"Please use this link.","example:7662:exzh2":"It serves as a link.","example:7662:exzh3":"We need better connections within the team.","example:7662:exzh4":"He's good at connecting people.","example:7662:exzh5":"This passage is a bridge to the next part of the story."},"7663":{"example:7663:exzh":"Please proceed in order.","example:7663:exzh2":"I'll explain in order.","example:7663:exzh3":"It needs to be processed one by one.","example:7663:exzh4":"Please arrange the files in order.","example:7663:exzh5":"We'll handle them one by one."},"7664":{"example:7664:exzh":"This core is important.","example:7664:exzh2":"She has a strong core.","example:7664:exzh3":"We need a leader with a strong core.","example:7664:exzh4":"Let's understand the core of this problem.","example:7664:exzh5":"We improved the core part."},"7665":{"example:7665:exzh":"Misuse is not allowed.","example:7665:exzh2":"Please don't misuse this data.","example:7665:exzh3":"The risk of misuse is high.","example:7665:exzh4":"He was arrested for misuse.","example:7665:exzh5":"Measures are needed to prevent misuse."},"7666":{"example:7666:exzh":"In physics, mechanics is important.","example:7666:exzh2":"We learn the laws of mechanics.","example:7666:exzh3":"He's an expert in mechanics.","example:7666:exzh4":"Mechanics is one of the difficult subjects.","example:7666:exzh5":"I'm interested in mechanics."},"7667":{"example:7667:exzh":"Kabul has beautiful scenery.","example:7667:exzh2":"He lives in Kabul.","example:7667:exzh3":"Kabul's culture is very rich.","example:7667:exzh4":"Every year, many tourists visit Kabul.","example:7667:exzh5":"The people of Kabul are very kind."},"7668":{"example:7668:exzh":"His body is weak because of illness.","example:7668:exzh2":"I'll rest so my weakened body can recover.","example:7668:exzh3":"As you age, your physical strength weakens.","example:7668:exzh4":"Weakness is bad for your health.","example:7668:exzh5":"Lack of exercise may cause weakness."},"7669":{"example:7669:exzh":"The school chime rang.","example:7669:exzh2":"My house has a doorbell.","example:7669:exzh3":"The chime lets us know when a visitor arrives.","example:7669:exzh4":"I like the chime at break time.","example:7669:exzh5":"He rang the bell and came in."},"7670":{"example:7670:exzh":"He's studying abroad in the US.","example:7670:exzh2":"Studying abroad is a big experience.","example:7670:exzh3":"I'm saving money so I can study abroad.","example:7670:exzh4":"My friend came back from studying abroad.","example:7670:exzh5":"Studying abroad in Japan is my dream.","grammar:7670:ex:trans":"He is studying in America.","grammar:7670:ex:structure":"アメリカに＋留学しています","grammar:7670:ex:explain":"「彼はアメリカに留学しています」. The key pattern is 「〜に留学する」, meaning study abroad in…; the place of study is marked with 「に」 (アメリカに). 「留学している」 uses 「ている」, which here expresses a continuing state, meaning he is currently in the middle of studying abroad. 「留学する」 is a suru-verb. The whole sentence is he is studying in America. Here 「ている」 focuses on describing an ongoing state.","grammar:7670:ex:words:0:zh":"he","grammar:7670:ex:words:0:note":"かれ","grammar:7670:ex:words:0:pos":"pronoun","grammar:7670:ex:words:1:zh":"(topic)","grammar:7670:ex:words:1:pos":"particle","grammar:7670:ex:words:2:zh":"America","grammar:7670:ex:words:2:pos":"noun","grammar:7670:ex:words:3:zh":"(the destination)","grammar:7670:ex:words:3:pos":"particle","grammar:7670:ex:words:4:zh":"study abroad","grammar:7670:ex:words:4:note":"りゅうがくして (te-form)","grammar:7670:ex:words:4:pos":"verb","grammar:7670:ex:words:5:zh":"(ongoing state)","grammar:7670:ex:words:5:pos":"auxiliary verb","grammar:7670:ex:points:0":"〜に留学する: study abroad in 〜 (アメリカに留学 = study abroad in America)","grammar:7670:ex:points:1":"〜ている: here it shows a continuing state (studying abroad)","grammar:7670:ex2:trans":"Studying abroad is a great experience.","grammar:7670:ex2:structure":"留学は＋大きな経験です","grammar:7670:ex2:words:0:zh":"study abroad","grammar:7670:ex2:words:0:note":"りゅうがく","grammar:7670:ex2:words:0:pos":"noun","grammar:7670:ex2:words:1:zh":"(topic)","grammar:7670:ex2:words:1:pos":"particle","grammar:7670:ex2:words:2:zh":"big","grammar:7670:ex2:words:2:note":"おおきな","grammar:7670:ex2:words:2:pos":"pre-noun adjectival","grammar:7670:ex2:words:3:zh":"experience","grammar:7670:ex2:words:3:note":"けいけん","grammar:7670:ex2:words:3:pos":"noun","grammar:7670:ex2:words:4:zh":"(assertion · polite)","grammar:7670:ex2:words:4:pos":"auxiliary verb","grammar:7670:ex2:points:0":"The pre-noun adjectival 「大きな」＋noun (a great experience)","grammar:7670:ex2:points:1":"AはBです: A is B","grammar:7670:ex3:trans":"I'm saving money so that I can study abroad.","grammar:7670:ex3:structure":"留学するために＋お金を貯めています","grammar:7670:ex3:words:0:zh":"study abroad","grammar:7670:ex3:words:0:note":"りゅうがくする","grammar:7670:ex3:words:0:pos":"verb","grammar:7670:ex3:words:1:zh":"for the sake of","grammar:7670:ex3:words:1:pos":"formal noun","grammar:7670:ex3:words:2:zh":"(purpose)","grammar:7670:ex3:words:2:pos":"particle","grammar:7670:ex3:words:3:zh":"money","grammar:7670:ex3:words:3:note":"おかね","grammar:7670:ex3:words:3:pos":"noun","grammar:7670:ex3:words:4:zh":"(object marker)","grammar:7670:ex3:words:4:pos":"particle","grammar:7670:ex3:words:5:zh":"save (money)","grammar:7670:ex3:words:5:note":"ためて (te-form)","grammar:7670:ex3:words:5:pos":"verb","grammar:7670:ex3:words:6:zh":"(action in progress)","grammar:7670:ex3:words:6:pos":"auxiliary verb","grammar:7670:ex3:points:0":"〜ために: in order to 〜 (purpose); it follows the dictionary form of a verb (留学するために)","grammar:7670:ex3:points:1":"「お金を貯める」 = save money; 〜ている shows an action in progress","grammar:7670:ex4:trans":"My friend came back from studying abroad.","grammar:7670:ex4:structure":"留学から帰って＋きました","grammar:7670:ex4:words:0:zh":"friend","grammar:7670:ex4:words:0:note":"ともだち","grammar:7670:ex4:words:0:pos":"noun","grammar:7670:ex4:words:1:zh":"(nominative)","grammar:7670:ex4:words:1:pos":"particle","grammar:7670:ex4:words:2:zh":"study abroad","grammar:7670:ex4:words:2:note":"りゅうがく","grammar:7670:ex4:words:2:pos":"noun","grammar:7670:ex4:words:3:zh":"from (starting point)","grammar:7670:ex4:words:3:pos":"particle","grammar:7670:ex4:words:4:zh":"come back","grammar:7670:ex4:words:4:note":"かえって (te-form with the small っ sound change)","grammar:7670:ex4:words:4:pos":"verb","grammar:7670:ex4:words:5:zh":"(movement toward the speaker)","grammar:7670:ex4:words:5:pos":"auxiliary verb","grammar:7670:ex4:points:0":"〜から帰る: come back from 〜 (留学から = back from studying abroad, i.e. from the place where one studied)","grammar:7670:ex4:points:1":"〜てくる: movement toward the speaker (帰ってきた = came back)","grammar:7670:ex5:trans":"Studying in Japan is my dream.","grammar:7670:ex5:structure":"日本での留学が＋夢です","grammar:7670:ex5:words:0:zh":"Japan","grammar:7670:ex5:words:0:note":"にほん","grammar:7670:ex5:words:0:pos":"noun","grammar:7670:ex5:words:1:zh":"at (a place)","grammar:7670:ex5:words:1:pos":"particle","grammar:7670:ex5:words:2:zh":"'s","grammar:7670:ex5:words:2:pos":"particle","grammar:7670:ex5:words:3:zh":"study abroad","grammar:7670:ex5:words:3:note":"りゅうがく","grammar:7670:ex5:words:3:pos":"noun","grammar:7670:ex5:words:4:zh":"(nominative)","grammar:7670:ex5:words:4:pos":"particle","grammar:7670:ex5:words:5:zh":"dream","grammar:7670:ex5:words:5:note":"ゆめ","grammar:7670:ex5:words:5:pos":"noun","grammar:7670:ex5:words:6:zh":"(assertion · polite)","grammar:7670:ex5:words:6:pos":"auxiliary verb","grammar:7670:ex5:points:0":"での＋noun: a 〜 in 〜 (日本での留学 = studying in Japan)","grammar:7670:ex5:points:1":"AがBです: A is B (留学が夢 = studying abroad is the dream)"},"7671":{"example:7671:exzh":"He's a veteran in that field.","example:7671:exzh2":"I want to learn the skills of a veteran.","example:7671:exzh3":"They are a team of veterans.","example:7671:exzh4":"A veteran's experience is very important.","example:7671:exzh5":"The veteran trained the new member."},"7675":{"example:7675:exzh":"He is a famous rock star.","example:7675:exzh2":"Rock star concerts are fun.","example:7675:exzh3":"She wants to become a rock star.","example:7675:exzh4":"Rock stars are very sensitive to fashion.","example:7675:exzh5":"Recent rock stars are very versatile."},"7676":{"example:7676:exzh":"He is skilled at this technique.","example:7676:exzh2":"Skilled craftsmen make the best works.","example:7676:exzh3":"Your skills improve by repeated practice.","example:7676:exzh4":"She is an experienced teacher.","example:7676:exzh5":"Skilled technique is required."},"7677":{"example:7677:exzh":"There is a time difference between Japan and the US.","example:7677:exzh2":"Because of the time difference, making phone calls is a hassle.","example:7677:exzh3":"I'll decide the departure time taking the time difference into account.","example:7677:exzh4":"While traveling, you need to watch out for the time difference.","example:7677:exzh5":"I didn't get enough sleep because of the time difference."},"7678":{"example:7678:exzh":"This movie is distributed internationally.","example:7678:exzh2":"The distribution method has changed.","example:7678:exzh3":"Food distribution is being carried out.","example:7678:exzh4":"A film distribution company was established.","example:7678:exzh5":"This work signed a special distribution contract."},"7680":{"example:7680:exzh":"Let's talk about another matter.","example:7680:exzh2":"He needs to prioritize another matter.","example:7680:exzh3":"I'm contacting you about another matter.","example:7680:exzh4":"How is the progress on the other matter?","example:7680:exzh5":"I'll deal with the other matter later."},"7681":{"example:7681:exzh":"Today is an unlucky day.","example:7681:exzh2":"I lost in the lottery draw.","example:7681:exzh3":"I picked the wrong option.","example:7681:exzh4":"That information was wrong.","example:7681:exzh5":"This time the product was a dud."},"7683":{"example:7683:exzh":"His work is done.","example:7683:exzh2":"Prices have been rising continuously lately.","example:7683:exzh3":"Her grades have been going up.","example:7683:exzh4":"He spoke in an upbeat tone.","example:7683:exzh5":"I hope money goes up."},"7684":{"example:7684:exzh":"I agreed to his proposal.","example:7684:exzh2":"After accepting all the conditions, we will sign the contract.","example:7684:exzh3":"To give consent, you need to check the details.","example:7684:exzh4":"I agreed to her opinion.","example:7684:exzh5":"It's important to acknowledge and accept."},"7685":{"example:7685:exzh":"He whispered to me.","example:7685:exzh2":"I heard her whisper.","example:7685:exzh3":"We whispered to each other on a quiet night.","example:7685:exzh4":"I can hear whispers of love.","example:7685:exzh5":"His whisper resonated in my heart."},"7686":{"example:7686:exzh":"That comet was named after its discoverer.","example:7686:exzh2":"We need to name this new drug.","example:7686:exzh3":"The naming ceremony will be held next week.","example:7686:exzh4":"We're thinking about a name for the new product.","example:7686:exzh5":"Residents were divided over the naming of the new station."},"7687":{"example:7687:exzh":"Since the contract is complete, we will carry out the handover.","example:7687:exzh2":"The documents need to be handed over.","example:7687:exzh3":"The handover date has been decided.","example:7687:exzh4":"The handover will take place in the afternoon.","example:7687:exzh5":"I can't wait for the project handover."},"7689":{"example:7689:exzh":"I eat rice every day.","example:7689:exzh2":"The rice is white rice.","example:7689:exzh3":"I use fresh rice in cooking.","example:7689:exzh4":"I'm good at cooking rice.","example:7689:exzh5":"There are many kinds of rice.","grammar:7689:ex:trans":"I eat rice every day.","grammar:7689:ex:structure":"毎日、米を食べます","grammar:7689:ex:explain":"「毎日、米を食べます」. The core word is 「米」, read こめ, meaning uncooked rice, raw rice grains. Note the difference from 「ご飯（ごはん）」 (cooked rice) and 「白米（はくまい）」; strictly speaking, what you eat is 「ご飯」, while 「米」 refers more to the grains themselves. 「毎日」 is a time noun used adverbially, with no particle. 「米を」 marks the object with 「を」. The whole sentence means (I) eat rice every day.","grammar:7689:ex:words:0:zh":"every day","grammar:7689:ex:words:0:note":"まいにち","grammar:7689:ex:words:0:pos":"noun","grammar:7689:ex:words:1:zh":"rice","grammar:7689:ex:words:1:note":"こめ","grammar:7689:ex:words:1:pos":"noun","grammar:7689:ex:words:2:zh":"(object marker)","grammar:7689:ex:words:2:pos":"particle","grammar:7689:ex:words:3:zh":"eat","grammar:7689:ex:words:3:note":"たべます","grammar:7689:ex:words:3:pos":"verb","grammar:7689:ex:points:0":"❗米（こめ）: rice, raw rice (uncooked grains); vs. 「ご飯（ごはん）」 = cooked rice; 「白米（はくまい）」 = white rice.","grammar:7689:ex:points:1":"米: raw rice (vs. ご飯 cooked rice).","grammar:7689:ex2:trans":"The rice is white rice.","grammar:7689:ex2:structure":"ご飯は白米です","grammar:7689:ex2:words:0:zh":"meal","grammar:7689:ex2:words:0:note":"ごはん","grammar:7689:ex2:words:0:pos":"noun","grammar:7689:ex2:words:1:zh":"(topic)","grammar:7689:ex2:words:1:pos":"particle","grammar:7689:ex2:words:2:zh":"white rice","grammar:7689:ex2:words:2:note":"はくまい","grammar:7689:ex2:words:2:pos":"noun","grammar:7689:ex2:words:3:zh":"(polite form)","grammar:7689:ex2:words:3:pos":"copula","grammar:7689:ex2:points:0":"❗白米: white rice (rice after milling).","grammar:7689:ex2:points:1":"白米: white rice.","grammar:7689:ex3:trans":"We use fresh rice for cooking.","grammar:7689:ex3:structure":"料理には新鮮な米を使います","grammar:7689:ex3:words:0:zh":"dish / cuisine","grammar:7689:ex3:words:0:note":"りょうり","grammar:7689:ex3:words:0:pos":"noun","grammar:7689:ex3:words:1:zh":"(object)","grammar:7689:ex3:words:1:pos":"particle","grammar:7689:ex3:words:2:zh":"(contrast)","grammar:7689:ex3:words:2:pos":"particle","grammar:7689:ex3:words:3:zh":"fresh","grammar:7689:ex3:words:3:note":"しんせん","grammar:7689:ex3:words:3:pos":"na-adjective","grammar:7689:ex3:words:4:zh":"(attributive form)","grammar:7689:ex3:words:4:pos":"auxiliary verb","grammar:7689:ex3:words:5:zh":"rice","grammar:7689:ex3:words:5:note":"こめ","grammar:7689:ex3:words:5:pos":"noun","grammar:7689:ex3:words:6:zh":"(object marker)","grammar:7689:ex3:words:6:pos":"particle","grammar:7689:ex3:words:7:zh":"use","grammar:7689:ex3:words:7:note":"つかいます","grammar:7689:ex3:words:7:pos":"verb","grammar:7689:ex3:points:0":"❗新鮮な米: freshly harvested rice.","grammar:7689:ex3:points:1":"新鮮な米: new rice.","grammar:7689:ex4:trans":"I'm good at cooking rice.","grammar:7689:ex4:structure":"米を炊くのが得意です","grammar:7689:ex4:words:0:zh":"rice","grammar:7689:ex4:words:0:note":"こめ","grammar:7689:ex4:words:0:pos":"noun","grammar:7689:ex4:words:1:zh":"(object marker)","grammar:7689:ex4:words:1:pos":"particle","grammar:7689:ex4:words:2:zh":"boil","grammar:7689:ex4:words:2:note":"たく","grammar:7689:ex4:words:2:pos":"verb","grammar:7689:ex4:words:3:zh":"(nominalizer)","grammar:7689:ex4:words:3:pos":"particle","grammar:7689:ex4:words:4:zh":"(object)","grammar:7689:ex4:words:4:pos":"particle","grammar:7689:ex4:words:5:zh":"good at","grammar:7689:ex4:words:5:note":"とくい","grammar:7689:ex4:words:5:pos":"na-adjective","grammar:7689:ex4:words:6:zh":"(polite form)","grammar:7689:ex4:words:6:pos":"copula","grammar:7689:ex4:points:0":"❗米を炊く: cook rice (炊く is the verb used specifically for cooking rice).","grammar:7689:ex4:points:1":"米を炊く: cook rice.","grammar:7689:ex5:trans":"There are many kinds of rice.","grammar:7689:ex5:structure":"米の種類はたくさんあります","grammar:7689:ex5:words:0:zh":"rice","grammar:7689:ex5:words:0:note":"こめ","grammar:7689:ex5:words:0:pos":"noun","grammar:7689:ex5:words:1:zh":"'s","grammar:7689:ex5:words:1:pos":"particle","grammar:7689:ex5:words:2:zh":"variety","grammar:7689:ex5:words:2:note":"しゅるい","grammar:7689:ex5:words:2:pos":"noun","grammar:7689:ex5:words:3:zh":"(topic)","grammar:7689:ex5:words:3:pos":"particle","grammar:7689:ex5:words:4:zh":"a lot","grammar:7689:ex5:words:4:pos":"adverb","grammar:7689:ex5:words:5:zh":"there is / are","grammar:7689:ex5:words:5:pos":"verb","grammar:7689:ex5:points:0":"❗米の種類: varieties of rice.","grammar:7689:ex5:points:1":"米の種類: varieties of rice."},"7690":{"example:7690:exzh":"This word can be rephrased.","example:7690:exzh2":"Rephrasing makes your writing richer.","example:7690:exzh3":"I'm practicing rephrasing.","example:7690:exzh4":"He's good at putting things in different words.","example:7690:exzh5":"Let's learn some simple rephrasings."},"7692":{"example:7692:exzh":"He is rumored to be using steroids.","example:7692:exzh2":"Steroids are widely used in medicine.","example:7692:exzh3":"Athletes' use of steroids is seen as a problem.","example:7692:exzh4":"You need to learn about the side effects of steroids.","example:7692:exzh5":"Steroid abuse has a bad effect on health."},"7693":{"example:7693:exzh":"Using a delivery service is convenient.","example:7693:exzh2":"He ordered food for delivery.","example:7693:exzh3":"Delivery services are increasing.","example:7693:exzh4":"I received a book by delivery.","example:7693:exzh5":"I'm thinking of ordering delivery this weekend."},"7694":{"example:7694:exzh":"His father has diabetes.","example:7694:exzh2":"Diabetes affects your diet.","example:7694:exzh3":"Regular checkups are necessary to prevent diabetes.","example:7694:exzh4":"She is receiving treatment for diabetes.","example:7694:exzh5":"Diabetes is a very tough disease."},"7695":{"example:7695:exzh":"The Pope is coming to visit.","example:7695:exzh2":"He once hoped to become the Pope.","example:7695:exzh3":"The Pope's message has been released.","example:7695:exzh4":"Believers all over the world respect the Pope.","example:7695:exzh5":"The Pope is a religious leader."},"7696":{"example:7696:exzh":"Transportation matters for the development of commerce.","example:7696:exzh2":"The world of commerce is fiercely competitive.","example:7696:exzh3":"She is studying commerce.","example:7696:exzh4":"Commercial activity supports the local economy.","example:7696:exzh5":"Through commerce, we meet many people."},"7697":{"example:7697:exzh":"Washing your hands is very important.","example:7697:exzh2":"Wash your hands before eating.","example:7697:exzh3":"Please remember to wash your hands.","example:7697:exzh4":"I wash my hands after coming back from outside.","example:7697:exzh5":"Washing your hands can prevent illness.","grammar:7697:ex:trans":"Washing your hands is very important.","grammar:7697:ex:structure":"手洗いは とても＋大切です","grammar:7697:ex:explain":"「手洗いはとても大切です」. The key word 「手洗い」 is the continuative (ren'yō) form of 「手を洗う」 (to wash your hands) turned into a noun — a verb becoming a noun. The pattern is 「〜は…大切だ」: 「手洗いは」 introduces the topic, and 「とても大切」 evaluates it (very important). 「とても」 is an adverb of degree, and 「大切」 is a na-adjective plus 「です」. The whole sentence means that washing your hands is very important. Making nouns from the continuative form is an important way of building Japanese words.","grammar:7697:ex:words:0:zh":"washing one's hands","grammar:7697:ex:words:0:note":"てあらい","grammar:7697:ex:words:0:pos":"noun","grammar:7697:ex:words:1:zh":"(topic)","grammar:7697:ex:words:1:pos":"particle","grammar:7697:ex:words:2:zh":"extremely","grammar:7697:ex:words:2:pos":"adverb","grammar:7697:ex:words:3:zh":"important","grammar:7697:ex:words:3:note":"たいせつ","grammar:7697:ex:words:3:pos":"na-adjective","grammar:7697:ex:words:4:zh":"(assertion · polite)","grammar:7697:ex:words:4:pos":"auxiliary verb","grammar:7697:ex:points:0":"〜が大切だ (topic は): 〜 is important (手洗いは…大切)","grammar:7697:ex:points:1":"verb continuative form turned into a noun: 手を洗う→手洗い (washing hands)","grammar:7697:ex2:trans":"You should wash your hands before eating.","grammar:7697:ex2:structure":"食事の前に手洗いを＋しましょう","grammar:7697:ex2:words:0:zh":"meal, eating","grammar:7697:ex2:words:0:note":"しょくじ","grammar:7697:ex2:words:0:pos":"noun","grammar:7697:ex2:words:1:zh":"'s","grammar:7697:ex2:words:1:pos":"particle","grammar:7697:ex2:words:2:zh":"before","grammar:7697:ex2:words:2:note":"まえ","grammar:7697:ex2:words:2:pos":"noun","grammar:7697:ex2:words:3:zh":"at (point in time)","grammar:7697:ex2:words:3:pos":"particle","grammar:7697:ex2:words:4:zh":"washing one's hands","grammar:7697:ex2:words:4:note":"てあらい","grammar:7697:ex2:words:4:pos":"noun","grammar:7697:ex2:words:5:zh":"(object marker)","grammar:7697:ex2:words:5:pos":"particle","grammar:7697:ex2:words:6:zh":"to do (volitional)","grammar:7697:ex2:words:6:pos":"verb","grammar:7697:ex2:points:0":"「〜の前に」 = before 〜 (食事の前に = before a meal)","grammar:7697:ex2:points:1":"〜ましょう: volitional / invitation (しましょう)","grammar:7697:ex3:trans":"Please remember to wash your hands.","grammar:7697:ex3:structure":"手洗いを忘れずに行って＋ください","grammar:7697:ex3:words:0:zh":"washing one's hands","grammar:7697:ex3:words:0:note":"てあらい","grammar:7697:ex3:words:0:pos":"noun","grammar:7697:ex3:words:1:zh":"(object marker)","grammar:7697:ex3:words:1:pos":"particle","grammar:7697:ex3:words:2:zh":"without forgetting; remember to","grammar:7697:ex3:words:2:note":"わすれずに","grammar:7697:ex3:words:2:pos":"verb (negative)","grammar:7697:ex3:words:3:zh":"to carry out; to do","grammar:7697:ex3:words:3:note":"おこなって (te-form)","grammar:7697:ex3:words:3:pos":"verb","grammar:7697:ex3:words:4:zh":"please (do)","grammar:7697:ex3:words:4:pos":"auxiliary verb","grammar:7697:ex3:points:0":"〜ずに: without 〜ing (忘れずに = without forgetting)","grammar:7697:ex3:points:1":"〜てください: please 〜 (行ってください)","grammar:7697:ex4:trans":"I wash my hands after coming home from outside.","grammar:7697:ex4:structure":"外から帰ったら手洗いを＋します","grammar:7697:ex4:words:0:zh":"outside","grammar:7697:ex4:words:0:note":"そと","grammar:7697:ex4:words:0:pos":"noun","grammar:7697:ex4:words:1:zh":"from (starting point)","grammar:7697:ex4:words:1:pos":"particle","grammar:7697:ex4:words:2:zh":"come back (conditional)","grammar:7697:ex4:words:2:note":"かえったら","grammar:7697:ex4:words:2:pos":"verb","grammar:7697:ex4:words:3:zh":"washing one's hands","grammar:7697:ex4:words:3:note":"てあらい","grammar:7697:ex4:words:3:pos":"noun","grammar:7697:ex4:words:4:zh":"(object marker)","grammar:7697:ex4:words:4:pos":"particle","grammar:7697:ex4:words:5:zh":"do","grammar:7697:ex4:words:5:pos":"verb","grammar:7697:ex4:points:0":"〜たら: after 〜, if 〜 (帰ったら = after coming back)","grammar:7697:ex4:points:1":"starting-point particle から: 外から (from outside)","grammar:7697:ex5:trans":"Washing your hands can prevent illness.","grammar:7697:ex5:structure":"手洗いをすると＋病気を予防できます","grammar:7697:ex5:words:0:zh":"washing one's hands","grammar:7697:ex5:words:0:note":"てあらい","grammar:7697:ex5:words:0:pos":"noun","grammar:7697:ex5:words:1:zh":"(object marker)","grammar:7697:ex5:words:1:pos":"particle","grammar:7697:ex5:words:2:zh":"do","grammar:7697:ex5:words:2:pos":"verb","grammar:7697:ex5:words:3:zh":"whenever…, if… (conditional)","grammar:7697:ex5:words:3:pos":"particle","grammar:7697:ex5:words:4:zh":"disease","grammar:7697:ex5:words:4:note":"びょうき","grammar:7697:ex5:words:4:pos":"noun","grammar:7697:ex5:words:5:zh":"(object marker)","grammar:7697:ex5:words:5:pos":"particle","grammar:7697:ex5:words:6:zh":"can prevent (potential)","grammar:7697:ex5:words:6:note":"よぼうできます","grammar:7697:ex5:words:6:pos":"verb","grammar:7697:ex5:points:0":"conditional 「と」: as soon as 〜, then 〜 (手洗いをすると = as soon as you wash your hands)","grammar:7697:ex5:points:1":"potential form: 予防できる (can prevent)"},"7698":{"example:7698:exzh":"He received certification.","example:7698:exzh2":"A new certification system will be introduced.","example:7698:exzh3":"Passing the certification exam is required.","example:7698:exzh4":"The product has international certification.","example:7698:exzh5":"We applied to a certification body."},"7699":{"example:7699:exzh":"Taking mock exams is important.","example:7699:exzh2":"He gave a mock lesson.","example:7699:exzh3":"We will practice mock interviews.","example:7699:exzh4":"I want to raise my score on the mock test.","example:7699:exzh5":"Mock experience is useful."}};